// environmentFromMetadata aggregates stored environment fingerprint metadata
// into an export-friendly object.
type environmentInfo struct {
        GoVersion string `json:"go_version"`
        OS        string `json:"os"`
        Arch      string `json:"arch"`
        Hostname  string `json:"hostname"`
}

func environmentFromMetadata(metadata map[string]string) environmentInfo {
        return environmentInfo{
                GoVersion: metadata["env_go_version"],
                OS:        metadata["env_os"],
                Arch:      metadata["env_arch"],
                Hostname:  metadata["env_hostname"],
        }
}

type exportPayload struct {
        *storage.StoredResult
        Environment environmentInfo `json:"environment"`
}

